local function dec(v)
    if type(v) ~= "table" then return v end
    local t, x = v.t, v.v
    if t == "V3" then return Vector3.new(x[1],x[2],x[3])
    elseif t == "V2" then return Vector2.new(x[1],x[2])
    elseif t == "C3" then return Color3.new(x[1],x[2],x[3])
    elseif t == "CF" then return CFrame.new(unpack(x))
    elseif t == "E" then return Enum[x[1]][x[2]]
    elseif t == "NR" then return NumberRange.new(x[1],x[2])
    elseif t == "NS" then
        local k = {}
        for _, a in ipairs(x) do table.insert(k, NumberSequenceKeypoint.new(a[1],a[2],a[3])) end
        return NumberSequence.new(k)
    elseif t == "CS" then
        local k = {}
        for _, a in ipairs(x) do table.insert(k, ColorSequenceKeypoint.new(a[1], Color3.new(a[2],a[3],a[4]))) end
        return ColorSequence.new(k)
    end
end

local blocos = {}
for linha in raw:gmatch("[^\r\n]+") do
    local a, k, tot, pedaco = linha:match("§(%d+)|(%d+)|(%d+)|(.-)¶")
    if a then
        a, k, tot = tonumber(a), tonumber(k), tonumber(tot)
        blocos[a] = blocos[a] or {tot = tot, p = {}}
        blocos[a].p[k] = pedaco
    end
end

local SKIP = {MeshId=true, TextureID=true, MeshSize=true, RenderFidelity=true}
local fallback, falhas, pendRefs, byId = 0, 0, {}, {}

local function build(d)
    local P = d.Props
    local inst, usouFallback

    if d.Class == "MeshPart" then
        local ok, mp = pcall(function()
            return InsertService:CreateMeshPartAsync(P.MeshId, Enum.CollisionFidelity.Box, Enum.RenderFidelity.Automatic)
        end)
        if ok and mp then
            inst = mp
        else
            inst = Instance.new("Part")
            local m = Instance.new("SpecialMesh")
            m.MeshType = Enum.MeshType.FileMesh
            m.MeshId = P.MeshId or ""
            m.TextureId = P.TextureID or ""
            local ms, s = dec(P.MeshSize), dec(P.Size)
            if ms and s then m.Scale = Vector3.new(s.X/ms.X, s.Y/ms.Y, s.Z/ms.Z) end
            m.Parent = inst
            usouFallback = true
            fallback += 1
        end
    else
        local ok, i = pcall(Instance.new, d.Class)
        if not ok then
            falhas += 1
            warn("classe nao criavel: " .. d.Class .. " (" .. d.Name .. ")")
            return nil
        end
        inst = i
    end

    inst.Name = d.Name
    for k, v in pairs(P) do
        if not (usouFallback and SKIP[k]) and k ~= "MeshSize" and k ~= "WorldPivot" then
            local ok = pcall(function() inst[k] = dec(v) end)
            if not ok and d.Name:lower() == "offset" then warn("Offset: falhou setar " .. k) end
        end
    end
    for k, v in pairs(d.Attrs or {}) do
        pcall(function() inst:SetAttribute(k, dec(v)) end)
    end

    byId[d.Id] = inst
    for nome, id in pairs(d.Refs or {}) do
        table.insert(pendRefs, {inst, nome, id})
    end

    for _, c in ipairs(d.Children) do
        local ch = build(c)
        if ch then ch.Parent = inst end
    end

    if P.WorldPivot and inst:IsA("Model") then
        pcall(function() inst.WorldPivot = dec(P.WorldPivot) end)
    end
    return inst
end

local pasta = Instance.new("Folder")
pasta.Name = "SwordsDual"
local total = 0

local indices = {}
for a in pairs(blocos) do table.insert(indices, a) end
table.sort(indices)

for _, a in ipairs(indices) do
    local b = blocos[a]
    local falta = {}
    for k = 1, b.tot do if not b.p[k] then table.insert(falta, k) end end
    if #falta == 0 then
        local ok, d = pcall(HttpService.JSONDecode, HttpService, table.concat(b.p))
        if ok and type(d) == "table" and d.Class then
            local p = build(d)
            if p then p.Parent = pasta total += 1 end
        else
            warn("filho " .. a .. ": JSON invalido")
        end
    else
        warn("filho " .. a .. ": faltam chunks " .. table.concat(falta, ",") .. " de " .. b.tot)
    end
end

local religados = 0
for _, r in ipairs(pendRefs) do
    local alvo = byId[r[3]]
    if alvo and pcall(function() r[1][r[2]] = alvo end) then religados += 1 end
end

pasta.Parent = RS

local offs = 0
for _, o in ipairs(pasta:GetDescendants()) do
    if o.Name:lower() == "offset" then offs += 1 end
end
print(total .. " filhos | fallback: " .. fallback .. " | falhas: " .. falhas .. " | refs: " .. religados .. "/" .. #pendRefs .. " | OFFSETS carregados: " .. offs)

