local Players, RS = game:GetService("Players"), game:GetService("ReplicatedStorage")
local plr = Players.LocalPlayer
if getgenv().FakeSwordUnload then pcall(getgenv().FakeSwordUnload) end

-- Lista de espadas (varre o ReplicatedStorage)
local RAIZ = RS:FindFirstChild("Assets") and RS.Assets:FindFirstChild("Swords")
if not RAIZ then warn("[FakeSword] ReplicatedStorage.Assets.Swords não encontrado, varrendo o ReplicatedStorage todo.") RAIZ = RS end
local ESPADAS, vistos, SWORDS = {}, {}, {}
for _, d in ipairs(RAIZ:GetDescendants()) do
    if d.Name == NOME_PART and d:IsA("BasePart") and d.Parent ~= RAIZ and not vistos[d.Parent.Name] then
        vistos[d.Parent.Name] = true
        SWORDS[d.Parent.Name] = d
        table.insert(ESPADAS, d.Parent.Name)
    end
end
table.sort(ESPADAS)

-- Duals: espadas da pasta SwordsDual (só na ltool)
local RAIZ_D = RS:FindFirstChild("SwordsDual", true)
local DUALS, DUAL_NOMES = {}, {}
if RAIZ_D then
    for _, d in ipairs(RAIZ_D:GetDescendants()) do
        if d.Name == NOME_DUAL and d:IsA("BasePart") and d.Parent ~= RAIZ_D and not DUALS[d.Parent.Name] then
            DUALS[d.Parent.Name] = d
            table.insert(DUAL_NOMES, d.Parent.Name)
        end
    end
else
    warn("[FakeSword] pasta SwordsDual não encontrada no ReplicatedStorage.")
end
table.sort(DUAL_NOMES)

local equipado, track, conns, sessaoAnim = false, nil, {}, 0
local fakes, ocultos, connsOc, vigia = {}, {}, {}, false
local cabeca
local slot, render

local function limparAnim()
    sessaoAnim += 1
    for _, c in ipairs(conns) do c:Disconnect() end
    conns = {}
    if track then pcall(function() track:Stop(FADE) track:Destroy() end) track = nil end
end

-- ══ ocultar / restaurar espadas originais ══
local ENABLED = {"ParticleEmitter", "Trail", "Beam", "Fire", "Smoke", "Sparkles", "PointLight", "SpotLight", "SurfaceLight", "Highlight"}

local function temEnabled(d)
    for _, c in ipairs(ENABLED) do if d:IsA(c) then return true end end
    return false
end

local function ehMeu(d)
    for _, f in ipairs(fakes) do
        if d == f or d:IsDescendantOf(f) then return true end
    end
    return false
end

local function ocultar(d)
    if ocultos[d] or ehMeu(d) then return end
    local prop
    if d:IsA("BasePart") or d:IsA("Decal") or d:IsA("Texture") then prop = "Transparency"
    elseif temEnabled(d) then prop = "Enabled" end
    if not prop then return end

    local alvo = (prop == "Transparency") and 1 or false
    ocultos[d] = {prop, d[prop]}
    d[prop] = alvo
    -- se o jogo mexer na propriedade enquanto equipado, forca de volta
    table.insert(connsOc, d:GetPropertyChangedSignal(prop):Connect(function()
        if equipado and ocultos[d] and d[prop] ~= alvo then d[prop] = alvo end
    end))
end

local function ocultarOriginais()
    local pasta = workspace:FindFirstChild(plr.Name .. " SwordWelds")
    if not pasta then return end
    for _, d in ipairs(pasta:GetDescendants()) do ocultar(d) end
    if not vigia then
        vigia = true
        table.insert(connsOc, pasta.DescendantAdded:Connect(function(d)
            if equipado then ocultar(d) end
        end))
    end
end

local function mostrarOriginais()
    for _, c in ipairs(connsOc) do c:Disconnect() end
    connsOc, vigia = {}, false
    for d, v in pairs(ocultos) do
        if d.Parent then pcall(function() d[v[1]] = v[2] end) end
    end
    ocultos = {}
end

-- ══ espadas falsas ══
local function limparEspada()
    for _, f in ipairs(fakes) do f:Destroy() end
    fakes = {}
end

local function offsetDe(objeto)
    local off = objeto:FindFirstChild("Offset")
    if off and off:IsA("CFrameValue") then return off.Value end
    if off and off:IsA("Vector3Value") then return CFrame.new(off.Value) end
    local function n(nm) local v = objeto:FindFirstChild(nm) return (v and v:IsA("NumberValue")) and v.Value or 0 end
    return CFrame.new(n("OffsetX"), n("OffsetY"), n("OffsetZ"))
end

local function colocarEspada()
    limparEspada()
    if not espadas.R and not espadas.L then return warn("[FakeSword] nenhuma espada selecionada.") end
    local char = plr.Character

    local nomePasta = plr.Name .. " SwordWelds"
    local pasta = workspace:FindFirstChild(nomePasta)
    if not pasta then
        pasta = Instance.new("Folder")
        pasta.Name = nomePasta
        pasta.Parent = workspace
    end

    for _, h in ipairs({"R", "L"}) do
        local nomeEsp = espadas[h]
        if nomeEsp then
            local orig = (h == "L" and lDual) and DUALS[nomeEsp] or SWORDS[nomeEsp]
            local objeto = orig and orig.Parent
            local t = char and char:FindFirstChild(PARTES[h], true)
            local part = t and (t:IsA("BasePart") and t or t:FindFirstChildWhichIsA("BasePart"))
            if not orig then
                warn("[PuxarObjeto] '" .. nomeEsp .. "' ou Part '" .. NOME_PART .. "' não encontrada.")
            elseif not part then
                warn("[PuxarObjeto] '" .. PARTES[h] .. "' não encontrado.")
            else
                local s = orig:Clone()
                s.Anchored = false
                s.CanCollide = false
                table.insert(fakes, s) -- registra antes do Parent pro vigia ignorar
                s.Parent = pasta
                local cf = (h == "L" and lDual and OFFS_DUAL[nomeEsp:lower()]) or offsetDe(objeto)
                s.CFrame = part.CFrame * cf

                local weld = Instance.new("Weld")
                weld.Part0, weld.Part1, weld.C0, weld.Parent = part, s, cf, s
            end
        end
    end
    if #fakes == 0 then return end

    ocultarOriginais()
    return true
end

local function limparCabeca()
    if cabeca then cabeca:Destroy() cabeca = nil end
end

local function colocarCabeca()
    limparCabeca()
    local head = plr.Character and plr.Character:FindFirstChild("Head")
    local orig = SWORDS[KATANA_CABECA]
    if not (head and orig) then return warn("[FakeSword] katana da cabeça não encontrada.") end

    cabeca = orig:Clone()
    cabeca.Anchored, cabeca.CanCollide, cabeca.CanTouch, cabeca.CanQuery, cabeca.Massless = false, false, false, false, true
    cabeca.CFrame = head.CFrame * CF_CABECA
    cabeca.Parent = head

    local weld = Instance.new("Weld")
    weld.Part0, weld.Part1, weld.C0, weld.Parent = head, cabeca, CF_CABECA, cabeca
end

local function tocarPose()
    limparAnim()
    local meu = sessaoAnim
    local char = plr.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local animator = hum and hum:FindFirstChildOfClass("Animator")
    if not animator then return end

    for _, t in ipairs(animator:GetPlayingAnimationTracks()) do pcall(function() t:Stop(0) end) end
    task.wait(0.1)
    if not equipado or sessaoAnim ~= meu then return end

    local a = Instance.new("Animation")
    a.AnimationId = "rbxassetid://" .. poseAtual
    local ok, t = pcall(function() return animator:LoadAnimation(a) end)
    a:Destroy()
    if not ok or not t then return warn("[FakeSword] Falha ao carregar pose " .. poseAtual) end

    local jinter = poseAtual == JINTER_ID
    t.Looped = true
    t.Priority = jinter and Enum.AnimationPriority.Action or Enum.AnimationPriority.Idle
    t:AdjustSpeed(SPEED)
    track = t

    local pulando = false

    -- Jinter: para a animação de andar/idle do jogo e mantém a pose tocando
    local function calar(alvo)
        for _, tr in ipairs(alvo and {alvo} or animator:GetPlayingAnimationTracks()) do
            local pr = tr.Priority
            if tr ~= t and (pr == Enum.AnimationPriority.Core or pr == Enum.AnimationPriority.Idle or pr == Enum.AnimationPriority.Movement) then
                pcall(function() tr:Stop(0) end)
            end
        end
    end
    if jinter then
        table.insert(conns, animator.AnimationPlayed:Connect(function(tr)
            if not pulando then calar(tr) end
        end))
    end

    table.insert(conns, hum.Running:Connect(function(speed)
        if jinter then
            if speed > 0 and not pulando then calar() end
            if not pulando and not t.IsPlaying then t:Play(FADE) t:AdjustSpeed(SPEED) end
        elseif speed > 0 then
            if t.IsPlaying then t:Stop(FADE) end
        elseif not pulando and not t.IsPlaying then
            t:Play(FADE) t:AdjustSpeed(SPEED)
        end
    end))
    table.insert(conns, hum.StateChanged:Connect(function(_, s)
        if s == Enum.HumanoidStateType.Jumping or s == Enum.HumanoidStateType.Freefall then
            pulando = true
            if jinter and t.IsPlaying then t:Stop(FADE) end
        elseif s == Enum.HumanoidStateType.Running or s == Enum.HumanoidStateType.RunningNoPhysics then
            pulando = false
            task.defer(function()
                if track == t and (jinter or hum.MoveDirection.Magnitude == 0) and not t.IsPlaying then
                    t:Play(FADE) t:AdjustSpeed(SPEED)
                end
            end)
        end
    end))
    t:Play(FADE)
end

