local CLICK_NORMAL, CLICK_DUAL, CLICK_HOLL = "86812198111738", "76877648916229", "94147829270060"
local CLICK_R = {}
local function reg(id, ...)
    for _, n in ipairs({...}) do CLICK_R[n:lower()] = id end
end
