reg("104930026196446", "Chrono Glaive", "Gearheart Glaive", "Dracolich Glaive")
reg("105577603924196", "Time Snipe")
reg("136755111495569", "Aetherfork")
reg("91935626239200", "Voidmizer", "Ionizer", "Atomizer")
reg("87427776864993", "Heavenly Hymn", "Windful Melodies")
