local aba = "Espadas"

local function atualizar()
    if equipado then
        if espadas.R or espadas.L then colocarEspada() else desequipar() end
    end
end

local function aplicar(nome)
    local alvo = ALVO[mao]
    if #alvo == 1 and espadas[alvo[1]] == nome and not (alvo[1] == "L" and lDual) then
        espadas[alvo[1]] = nil
    else
        for _, h in ipairs(alvo) do espadas[h] = nome end
        if table.find(alvo, "L") then lDual = false end
    end
    atualizar()
end

-- Duals: sempre na esquerda (ltool); clicar de novo tira
local function aplicarDual(nome)
    if lDual and espadas.L == nome then
        espadas.L, lDual = nil, false
    else
        espadas.L, lDual = nome, true
    end
    atualizar()
end

render = function()
    slot.Text = "R: " .. (espadas.R or "-") .. "\nL: " .. (espadas.L or "-")
    tabE.BackgroundColor3 = aba == "Espadas" and GREEN or GRAY
    tabP.BackgroundColor3 = aba == "Poses" and GREEN or GRAY
    tabD.BackgroundColor3 = aba == "Duals" and GREEN or GRAY
    btn3.Text = (estilo3 and "[x] " or "[ ] ") .. "Estilo 3 espadas"
    btn3.BackgroundColor3 = estilo3 and GREEN or GRAY
    btnClicks.Text = (testeClicks and "[x] " or "[ ] ") .. "Teste de Clicks"
    btnClicks.BackgroundColor3 = testeClicks and GREEN or GRAY
    offBox.Visible = aba == "Duals"
    if not offBox:IsFocused() then offBox.Text = textoOff() end
    for k, b in pairs(btnMao) do b.BackgroundColor3 = mao == k and GREEN or GRAY b.Visible = aba ~= "Duals" end
    for _, c in ipairs(lista:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end

    local q = busca.Text:lower()
    for _, item in ipairs(aba == "Espadas" and ESPADAS or aba == "Poses" and POSES or DUAL_NOMES) do
        local nome, id = item, nil
        if type(item) == "table" then nome, id = item[1], item[2] end
        if q == "" or nome:lower():find(q, 1, true) then
            local tag = ""
            if not id then
                if aba == "Duals" then
                    tag = (lDual and espadas.L == nome) and "L" or ""
                else
                    tag = (espadas.R == nome and "R" or "") .. ((espadas.L == nome and not lDual) and "L" or "")
                end
            end
            local sel = id and id == poseAtual or (not id and tag ~= "")
            local b = mk("TextButton", {Size = UDim2.new(1, -6, 0, 26), BackgroundColor3 = sel and GREEN or GRAY, TextColor3 = WHITE,
                Text = "  " .. nome .. (tag ~= "" and ("   [" .. tag .. "]") or ""), TextXAlignment = Enum.TextXAlignment.Left,
                Font = Enum.Font.Gotham, TextSize = 13}, lista)
            mk("UICorner", {}, b)
            b.MouseButton1Click:Connect(function()
                if id then
                    poseAtual = id
                    if equipado then task.spawn(tocarPose) end
                elseif aba == "Duals" then
                    aplicarDual(nome)
                else
                    aplicar(nome)
                end
                render()
            end)
        end
    end
end

tabE.MouseButton1Click:Connect(function() aba = "Espadas" render() end)
tabP.MouseButton1Click:Connect(function() aba = "Poses" render() end)
tabD.MouseButton1Click:Connect(function() aba = "Duals" render() end)
busca:GetPropertyChangedSignal("Text"):Connect(render)
busca.FocusLost:Connect(function(enter)
    if enter and aba == "Espadas" and SWORDS[busca.Text] then
        aplicar(busca.Text)
        render()
    elseif enter and aba == "Duals" and DUALS[busca.Text] then
        aplicarDual(busca.Text)
        render()
    end
end)

abrir.MouseButton1Click:Connect(function() painel.Visible = not painel.Visible end)
slot.MouseButton1Click:Connect(function() if equipado then desequipar() else equipar() end end)
plr.CharacterAdded:Connect(desequipar)

getgenv().FakeSwordUnload = function() cDefl:Disconnect() cVigiaDefl:Disconnect() desequipar() gui:Destroy() end
render()
